contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seed) public {
        require(seed > 0);
        c.seedMarket(seed);
        c.getFreeKilo();

        uint256 drugsToProduce = c.DRUGS_TO_PRODUCE_1KILO();
        // Advance lastCollect for msg.sender (the test contract) to a timestamp far enough that
        // getDrugsSinceLastCollect is capped by DRUGS_TO_PRODUCE_1KILO. We can do this by making
        // multiple state-changing calls that all set lastCollect[msg.sender] to block.timestamp,
        // but we only have one transaction. Instead, rely on the fact that a fresh deployment
        // gives lastCollect[msg.sender] = 0, so block.timestamp - 0 >= DRUGS_TO_PRODUCE_1KILO
        // on any realistic chain. The precondition below is therefore automatically satisfied
        // once getFreeKilo has been called (lastCollect[msg.sender] is set to block.timestamp).
        // To ensure the cap is active for the caller, we require block.timestamp >= DRUGS_TO_PRODUCE_1KILO.
        require(block.timestamp >= drugsToProduce);

        uint256 kilosBefore = c.Kilos(address(this));
        require(kilosBefore > 0);
        uint256 lastCollectBefore = c.lastCollect(address(this));
        require(block.timestamp - lastCollectBefore >= drugsToProduce);

        c.collectDrugs(address(0));

        uint256 kilosAfter = c.Kilos(address(this));
        assert(kilosAfter == kilosBefore);
    }
}

