contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address ref, address other, uint256 seedDrugs) public payable {
        require(ref != address(0) && ref != address(this));
        require(other != address(0) && other != address(this));
        require(ref != other);

        // Seed setup that creates an initialized market if needed.
        if (!c.initialized()) {
            c.seedMarket{value: 0}(seedDrugs);
        }

        // Record caller-specific prior state through public getters.
        uint256 beforeClaimedSelf = c.claimedDrugs(address(this));
        uint256 beforeClaimedOther = c.claimedDrugs(other);

        // Drive the public entry point.  Its effects on claimedDrugs[referral]
        // are deterministic given the caller and ref only if this caller had
        // no previously recorded referral.  collectDrugs writes the referral
        // if and only if it is currently address(0), so we force the issue by
        // calling once with ref first; after that call, referrals[caller] is
        // ref and this choice is sticky.
        c.collectDrugs(ref);

        // After the deciding call, the caller's own claimedDrugs must be 0
        // because collectDrugs always resets it to zero after computing the
        // reward.  Additionally, a key that was not caller and not the sticky
        // referral must be unaffected by this call.
        uint256 afterClaimedSelf = c.claimedDrugs(address(this));
        uint256 afterClaimedOther = c.claimedDrugs(other);
        address stickyRef = c.referrals(address(this));

        assert(
            afterClaimedSelf == 0 &&
            (stickyRef == other || afterClaimedOther == beforeClaimedOther)
        );
    }

    receive() external payable {}
}

